Vh Expression
Expression contains name, aggregate, index var, literal, qualified expression, type
conversion, function call, and operation.

function func_test(signal dividend: integer; signal divisor: integer)
return integer is
return dividend/divisor;
-- procedure body
procedure opr_testing (signal cnt: inout integer; signal flag: in
std_logic; signal in_arr: in std_logic_vector (2 downto 0)) is
variable lcv: std_logic := '0';
variable lcvv: std_logic_vector(1 downto 0) := "00";
variable lcbv: bit_vector(15 downto 0) := x"0000";
----------------------------------------------------------------------------- operation test

----------------------------------------------------------------------------- logical operator
lcv := lcv and in_arr(0);
lcv := lcvv(0) or flag;
lcvv:= lcvv(1 downto 0) nand in_arr(2 downto 1);
lcv := lcv nor flag;
lcv := lcv xor flag;
lcv := lcv xnor flag;
-- relational operator
if flag = '0' then
elsif flag /= '0' then
elsif flag < '0' then
elsif flag <= '0' then
elsif flag > '0' then
elsif flag >= '0' then
-- shift operator
lcbv := lcbv sll 2;
lcbv := lcbv srl 2;
lcbv := lcbv sla 2;
lcbv := lcbv sra 2;
lcbv := lcbv rol 2;
lcbv := lcbv ror 2;
-- adding operator
cnt <= cnt + 0;
cnt <= cnt - 0;
lcvv := lcv & flag;
-- sign
cnt <= + cnt;
cnt <= - cnt;
-- multiplying operator
cnt <= cnt * 1;
cnt <= cnt / 1;
cnt <= cnt mod 1;
cnt <= cnt rem 1;
-- miscellaneous operator
cnt <= cnt ** 1;
cnt <= abs cnt;
lcv := not flag;
-- mixed test + funcCall
cnt <= cnt ** ((cnt*1) + func_test(cnt, cnt));

