architecture arch_sub of sub is -- npiDmVhArchitecture
port(oo: out std_logic);
component add -- npiDmVhComponent
port(ea : in std_logic_vector(size-1 downto 0);
eb : in std_logic_vector(size-1 downto 0);
esum : out std_logic_vector(size-1 downto 0);
end component add;
-- npiDmVhInstance: instantiate add with component declaration
inst_add: add generic map(size => 32)
port map(a, b, cin, sum, cout);
-- npiDmVhInstance: instantiate sub with direct instantiation method
inst_sub: entity work.sub(arch_sub) port map(oo => oo);

port(ea : in std_logic_vector(size-1 downto 0);
