void trace_driver(npiNlHandle hdl, FILE* fp)
{
nlHdlVec_t dHdlVec;
nlHdlVec_t::iterator it;
if(npi_vanl_driver_by_hdl(hdl, dHdlVec/*O*/) == 0)
{
fprintf (fp, "-> %s, (%s)\n",
npi_nl_ut_get_hdl_info(hdl),
npi_vanl_get_value_by_hdl(hdl, npiNlBinFormat));
}
for (it = dHdlVec.begin(); it != dHdlVec.end(); ++it)
trace_driver(*it, fp);
}
{
npi_vanl_begin ("top");
npi_vanl_set_value_from_file ("setValue.log");
npi_vanl_propagate_value ();
//-------------- driver load testing -------------npiNlHandle hdl = npi_nl_L1_handle_by_name("top.w1");
printf("trace driver recursively 1: %s\n",
npi_nl_ut_get_hdl_info(hdl));
trace_driver(hdl, stdout);
hdl = npi_nl_L1_handle_by_name("top.w3");
printf("trace driver recursively 2: %s\n",
npi_nl_ut_get_hdl_info(hdl));
trace_driver(hdl, stdout);

}

// -------------- end of trace driver load -------------npi_vanl_end();

