npi_nl_ut_dump_hdl_info(instHdlStats.hdlArr[i], stdout);
for (i=0; i<portHdlStats.hdlNo; i++)
npi_nl_ut_dump_hdl_info(portHdlStats.hdlArr[i], stdout);
printf("Found %d instances and %d ports\n", instHdlStats.hdlNo,
portHdlStats.hdlNo);
}
{
