npiFsdbwStreamHandle npi_tr_writer::create_stream(string
stream_full_name, const char* obj_channel){
// Create a new stream.
npiFsdbwStreamHandle streamHdl = npi_fsdbw_stream_begin( m_file,
stream_full_name.c_str() );
// if obj_channel is given, add an attribute to a stream :
"%obj_channel%"
if( strcmp(obj_channel, "") != NPI_TR_WRITER_EQUAL ){
//string stream_attr_value("%");
//stream_attr_value.append(obj_channel);
//stream_attr_value.append("%");
//npi_fsdbw_stream_add_attr( streamHdl, "channel",
stream_attr_value.c_str() );
npi_fsdbw_stream_add_attr( streamHdl, "channel", obj_channel);
}
// if the given protocol name (m_prot_scope_full_path) is not empty and
hasn't existing yet, add it as scope attribute
if( ( m_prot_scope_full_path != "" ) &&
( FSDB->get_pro_count(m_prot_scope_full_path.c_str() ) == 0 ) ){
npi_fsdbw_scope_add_attr(m_file, m_prot_fsdb_stream_parent.c_str(),
"snps_vip_version", m_protocol_version.c_str() );

npi_fsdbw_scope_add_attr(m_file, m_prot_fsdb_stream_parent.c_str(),
"snps_protocol_name", m_prot_scope_full_path.c_str() );
FSDB->add_protocol_to_array(m_prot_scope_full_path.c_str(), true);
}
if( streamHdl != NULL ){
FSDB->add_stream_to_array(stream_full_name, streamHdl);
npi_fsdbw_stream_end(streamHdl);
}
return streamHdl;

}

npiFsdbwStreamHandle npi_tr_writer::get_stream_handle_by_type(const char*
obj_type, const char* obj_channel){
npiFsdbwStreamHandle streamHdl = NULL;
string stream_full_name( obj_type );
if ( m_prot_fsdb_stream_parent == "" )
return streamHdl;
// To be used later for creating stream based on both object_type and
channel
// if obj_channel is not empty, set "stream_full_name" as
"m_prot_fsdb_stream_parent.obj_type.obj_channel"
// otherwise, set is as "m_prot_fsdb_stream_parent"
stream_full_name = create_stream_full_name(obj_channel, obj_type);
// Check if the stream already exists. If so, return the stream id.
if( FSDB->stream_exist(stream_full_name) ){
streamHdl = FSDB->get_stream_handle(stream_full_name);
return streamHdl;
}
// Create a new stream.
streamHdl = create_stream(stream_full_name, obj_channel);
}

return streamHdl;

