const char* npi_tr_writer::create_object(const char* obj_type, const
char* obj_uid,
const char* obj_channel,
npiFsdbTime time){
// Make sure that the object can be created for the desired transaction
// (that is, protocol-level transaction or memory transaction). If
not, return
// an empty string.
if( m_prot_xact_recording_enabled == false ){
obj_uid = NPI_TR_WRITER_DEFAULT_OBJ_ID;
return obj_uid;
}
// if the obj id is not given, set it as "obj_type"_"obj_type_count"
if( strcmp( obj_uid, NPI_TR_WRITER_DEFAULT_OBJ_ID ) ==
NPI_TR_WRITER_EQUAL ){
obj_uid = create_new_obj_uid(obj_type);
}
// Create a new object.
npi_tr_writer_object* tr_object = new npi_tr_writer_object(obj_type,
obj_uid, obj_channel);
// Add the newly-created object to the array of unended objects.
string obj_uid_str = obj_uid;
m_unended_objects[ obj_uid_str ] = tr_object;
//print_unended_objects();
// get a stream handle, if it is not existing, create a new one
npiFsdbwStreamHandle streamHdl = NULL;
streamHdl = get_stream_handle_by_type(obj_type, obj_channel);
//set the begin time
bool timeIsGiven = false;// flag for marking if begin time is given
if( time == NPI_TR_WRITER_DEF_BEGIN_TIME ) // if the argument "time" is
not given
tr_object->set_begin_time( FSDB->get_current_time() );
tr_object->set_begin_time( time );

timeIsGiven = true;
}
// create a new transaction on this stream
create_transaction(streamHdl, tr_object, obj_type, obj_channel,
timeIsGiven);

}

// Return the uid of the newly-created object.
return obj_uid;

