bool write_relation_in_objects( map <string, npi_tr_writer_object*>*
object_map, npi_tr_writer* tr_writer ) {
if( !object_map || !tr_writer ) {
printf("write_relation_in_objects fail. \n");
}
for( map<string, npi_tr_writer_object*>::iterator it =
object_map->begin();
it != object_map->end(); ++it ){
if( !tr_writer->write_object( it->second ) ) {
printf("write un-ended object function failed
(npi_tr_writer_FSDB_close function)\n");
}
}

// write_relations in npi_tr_writer_FSDB_close() instead of end_object()
or flush_writer()
// main reason: npi_fsdbw_add_relation can only be called after
npi_fsdbw_trans_end()
bool npi_tr_writer_write_relations( npi_tr_FSDB* FSDB ) {
if( !FSDB ) {
printf( " npi_tr_FSDB is NULL. npi_tr_writer_write_relations()\n ");
}
map <npi_tr_writer*, bool>* tr_writer_table =
FSDB->get_tr_writer_table();
if( !tr_writer_table )
for(map<npi_tr_writer*, bool>::iterator it = tr_writer_table->begin();
it != tr_writer_table->end(); ++it){
if( it->second == true ) {
npi_tr_writer* tr_writer = it->first;
if( !tr_writer )
if( !write_relation_in_objects( tr_writer->get_unended_objects(),
tr_writer ) ) {
printf(" un-ended objects write relation fail\n");
}
if( !write_relation_in_objects( tr_writer->get_ended_objects(),
tr_writer ) ) {
printf(" ended objects write relation fail\n");
}

}

}
}

void npi_tr_writer_FSDB_close(){
// write_relations in npi_tr_writer_FSDB_close() instead of
end_object() or flush_writer()
// main reason: npi_fsdbw_add_relation can only be called after
npi_fsdbw_trans_end()
if( !npi_tr_writer_write_relations( FSDB ) ) {
printf("write relation error. npi_tr_writer_write_relations()\n");
}

}

FSDB->close_FSDB();
npi_tr_FSDB::del_instance();

