---------------------------------------------------------------------------function string verdi_pa_writer::get_legal_fsdb_name( string name );
string res_name = name;

int len = res_name.len();
for ( int i = 0; i < len; i++ )
if ( ( res_name[ i ] == "." ) || ( res_name[ i ] == "/" ) ||
( res_name[ i ] == " " ) )
if ( res_name[ i ] == " " )
verdi_pa_writer_warning( "get_legal_fsdb_name", "Naming
issue; the
name contains a
space" )

end

res_name[ i ] = "_";
end

return res_name;
end
//----------------------------------------------------------------------------function longint unsigned verdi_pa_writer::get_stream_id_by_type( string
object_type, string object_channel );
longint unsigned stream_id = 0;
string stream_full_name = object_type;
static string st_stream_full_name = "";
// For later use with scope attribute
string combined_protocol_name = "";
if ( this.fsdb_stream_parent == "" )
return stream_id;
// To be used later for creating stream based on both object_type and
channel
if ( object_channel != "" )
stream_full_name = { this.fsdb_stream_parent, ".", object_type,
".",
object_channel };
stream_full_name = { this.fsdb_stream_parent, ".", object_type };
// Check if the stream already exists. If so, return the stream id.

if ( stream_id_array.exists( stream_full_name ) )
stream_id = stream_id_array[ stream_full_name ];
return stream_id;
end
// Create a new stream.
st_stream_full_name = stream_full_name;
stream_id = $fsdbTrans_create_stream_begin( st_stream_full_name );
if ( object_channel != "" )
static string st_stream_attr_value = "";
st_stream_attr_value = { "%", object_channel, "%" };
$fsdbTrans_add_stream_attribute( stream_id, st_stream_attr_value,
"+name+channel" );
end
combined_protocol_name = this.scope_full_path;
if ( ( combined_protocol_name != "" ) && ( !
protocol_name_array.exists( combined_protocol_name ) ) )
static string st_protocol_name = "";
static string st_version_info = "";
static string protocol_info
= "protocol";
static string st_version_info_arg = { "+name+",
"snps_vip_version" };
static string protocol_info_arg
= { "+name+",
"snps_protocol_info" };
static string protocol_name_arg
= { "+name+",
"snps_protocol_name" };
st_protocol_name
= combined_protocol_name;
st_version_info
= this.protocol_version;
st_stream_full_name = this.fsdb_stream_parent;
$fsdbTrans_add_scope_attribute( st_stream_full_name,
st_version_info,
st_version_info_arg );
$fsdbTrans_add_scope_attribute( st_stream_full_name,
st_protocol_name,
protocol_name_arg );
protocol_name_array[ combined_protocol_name ] = 1;
end
if ( stream_id != 0 )
stream_id_array[ stream_full_name ] = stream_id;
$fsdbTrans_create_stream_end( stream_id );

end
return stream_id;
end
