scaled_time = 100us;
if ( scaled_time == 0 ) return "1ms";
scaled_time = 10us;
if ( scaled_time == 0 ) return "100us";
scaled_time = 1us;

if ( scaled_time == 0 ) return "10us";
scaled_time = 100ns;
if ( scaled_time == 0 ) return "1us";
scaled_time = 10ns;
if ( scaled_time == 0 ) return "100ns";
scaled_time = 1ns;
if ( scaled_time == 0 ) return "10ns";
scaled_time = 100ps;
if ( scaled_time == 0 ) return "1ns";
scaled_time = 10ps;
