output mux; reg mux;
input clk,s0,s1,i0,i1,i2,i3;
table
f 0 0 0 ? ? ? : ? : 0;
f 0 0 1 ? ? ? : ? : 1;
f 0 1 ? 0 ? ? : ? : 0;
f 0 1 ? 1 ? ? : ? : 1;
f 1 0 ? ? 0 ? : ? : 0;
f 1 0 ? ? 1 ? : ? : 1;
f 1 1 ? ? ? 0 : ? : 0;
