variable JK : std_logic_vector ( 1 downto 0);
wait until (CLK'event and CLK = '1');
JK := (J & K);
case JK is
when "01" => Q <= '0';
when "10" => Q <= '1'
when "11" => Q <= not (Q);
when "00" => Q <= Q;
when others => Q <= 'X';
Q_out <= Q;
