// wrapper for vc_StringToVector().

`define FILE_NAME_SIZE 512

module Test;
reg [`FILE_NAME_SIZE*8:1] file_name;
// this file_name will be passed to the Verilog code that expects
// a Verilog-like string
.
.
.
initial begin
