module wrealsum_to_logic (input wrealsum wsum, output logic l);
always @(wsum) begin
if (wsum == `wrealXState) l = 1'bx;
else if (wsum == `wrealZState) l = 1'bz;
else if (wsum <= 0.5) l = 1'b0;
else if (wsum >= 3.5) l = 1'b1;

